window.ScripturaLexicons.BDAG_PART_0170 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-01\" data-source=\"BDAG\" data-search=\"θραυματίζω verbo quebrar; despedaçar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θραυματίζω</td><td>verbo</td><td>quebrar; despedaçar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-02\" data-source=\"BDAG\" data-search=\"θραύω verbo quebrar; despedaçar; invalidar; oprimir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θραύω</td><td>verbo</td><td>quebrar; despedaçar; invalidar; oprimir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-03\" data-source=\"BDAG\" data-search=\"θρέμμα, ατος, τό substantivo neutro animal doméstico; ovelha; cabra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θρέμμα, ατος, τό</td><td>substantivo neutro</td><td>animal doméstico; ovelha; cabra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-04\" data-source=\"BDAG\" data-search=\"θρηνέω verbo lamentar; prantear; entoar lamentação fúnebre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θρηνέω</td><td>verbo</td><td>lamentar; prantear; entoar lamentação fúnebre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-05\" data-source=\"BDAG\" data-search=\"θρῆνος, ου, ὁ substantivo masculino lamento fúnebre; lamentação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θρῆνος, ου, ὁ</td><td>substantivo masculino</td><td>lamento fúnebre; lamentação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-06\" data-source=\"BDAG\" data-search=\"θρησκεία, ας, ἡ substantivo feminino culto; adoração; prática religiosa; religião BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θρησκεία, ας, ἡ</td><td>substantivo feminino</td><td>culto; adoração; prática religiosa; religião</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-07\" data-source=\"BDAG\" data-search=\"θρησκεύω verbo prestar culto; adorar; praticar ritos religiosos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θρησκεύω</td><td>verbo</td><td>prestar culto; adorar; praticar ritos religiosos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-08\" data-source=\"BDAG\" data-search=\"θρησκός, όν adjetivo de dois gêneros religioso; devoto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θρησκός, όν</td><td>adjetivo de dois gêneros</td><td>religioso; devoto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-09\" data-source=\"BDAG\" data-search=\"θριαμβεύω verbo conduzir em triunfo; triunfar sobre; expor publicamente; tornar conhecido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θριαμβεύω</td><td>verbo</td><td>conduzir em triunfo; triunfar sobre; expor publicamente; tornar conhecido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-10\" data-source=\"BDAG\" data-search=\"θρίξ, τριχός, ἡ substantivo feminino pelo; cabelo; fio de cabelo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θρίξ, τριχός, ἡ</td><td>substantivo feminino</td><td>pelo; cabelo; fio de cabelo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-11\" data-source=\"BDAG\" data-search=\"θροέω verbo perturbar-se; assustar-se; ficar alarmado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θροέω</td><td>verbo</td><td>perturbar-se; assustar-se; ficar alarmado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-12\" data-source=\"BDAG\" data-search=\"θρόμβος, ου, ὁ substantivo masculino gota; gota de sangue; coágulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θρόμβος, ου, ὁ</td><td>substantivo masculino</td><td>gota; gota de sangue; coágulo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-13\" data-source=\"BDAG\" data-search=\"θρόνος, ου, ὁ substantivo masculino cadeira; assento; trono; soberania; potestade entronizada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θρόνος, ου, ὁ</td><td>substantivo masculino</td><td>cadeira; assento; trono; soberania; potestade entronizada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-14\" data-source=\"BDAG\" data-search=\"θρύπτω verbo quebrar em pequenos pedaços; esmigalhar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θρύπτω</td><td>verbo</td><td>quebrar em pequenos pedaços; esmigalhar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-15\" data-source=\"BDAG\" data-search=\"Θυάτειρα (-ιρα), ων, τά nome geográfico neutro plural Tiatira; cidade da Lídia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Θυάτειρα (-ιρα), ων, τά</td><td>nome geográfico neutro plural</td><td>Tiatira; cidade da Lídia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-16\" data-source=\"BDAG\" data-search=\"θυγάτηρ, τρός, ἡ substantivo feminino filha; mulher tratada como filha; descendente; filha de Sião BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θυγάτηρ, τρός, ἡ</td><td>substantivo feminino</td><td>filha; mulher tratada como filha; descendente; filha de Sião</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-17\" data-source=\"BDAG\" data-search=\"θυγάτριον, ου, τό substantivo neutro diminutivo filhinha; filha querida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θυγάτριον, ου, τό</td><td>substantivo neutro diminutivo</td><td>filhinha; filha querida</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-18\" data-source=\"BDAG\" data-search=\"θύελλα, ης, ἡ substantivo feminino tempestade; vendaval; redemoinho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θύελλα, ης, ἡ</td><td>substantivo feminino</td><td>tempestade; vendaval; redemoinho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-19\" data-source=\"BDAG\" data-search=\"θύϊνος, η, ον adjetivo de madeira de tuia; de madeira aromática BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θύϊνος, η, ον</td><td>adjetivo</td><td>de madeira de tuia; de madeira aromática</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0170-20\" data-source=\"BDAG\" data-search=\"θῦμα, ατος, τό substantivo neutro sacrifício; oferta sacrificial BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θῦμα, ατος, τό</td><td>substantivo neutro</td><td>sacrifício; oferta sacrificial</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0170-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θραυματίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Quebrar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:18</a>, na variante do Códice D; ver <span class=\"greek\">θραύω</span>, acepção 3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θραύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Futuro <span class=\"greek\">θραύσω</span>, LXX; 1º aoristo <span class=\"greek\">ἔθραυσα</span>. Passiva: futuro, 3ª pessoa do singular <span class=\"greek\">θραυσθήσεται</span>, LXX; 1º aoristo <span class=\"greek\">ἐθραύσθην</span>; particípio perfeito <span class=\"greek\">τεθραυσμένος</span> (ver verbete anterior; Píndaro, Heródoto e outros; Vécio Valente; inscrições, papiros, LXX; PsSol 17:22. Uso figurado em algumas dessas fontes; ver também Máximo de Tiro 14, 6e; Cat. Cod. Astr. VIII p. 147, 12; Josefo, Bell. 1, 323). Sentido geral: «quebrar em pedaços».</p><p class=\"entry-text\">① Fazer alguma coisa partir-se em pedaços: quebrar, despedaçar (Diodoro Sículo 20, 93, 2; SIG2 588, 27 [séc. II a.C.]; Kaibel 1003, 3; Josefo, Ant. 8, 390), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:3</a>, variante de leitura. A respeito de objetos de cerâmica, Hm 11:13.</p><p class=\"entry-text\">② Fazer alguma coisa perder sua validade: quebrar, anular; extensão figurada da acepção 1, Dg 11:5.</p><p class=\"entry-text\">③ Fazer alguém ficar oprimido: quebrantar, enfraquecer, oprimir; extensão figurada da acepção 1 (Hinos Órficos 87, 3 <span class=\"greek\">ψυχήν</span>; Plutarco, Anton. 923 [17, 4] <span class=\"greek\">θραυόμενος</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λογισμόν</span>; Marco Aurélio 4, 49, 2), Hv 3, 11, 3. <span class=\"greek\">τεθραυσμένοι</span>, «os oprimidos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:18</a>; B 3:3 (ambos em Is 58:6). — DELG; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρέμμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">τρέφω</span>; autores trágicos e outros.) Animal doméstico, especialmente ovelha ou cabra (Xenofonte, Oec. 20, 23 e outros; SIG 636, 26; 826g, 20; OGI 200, 11; 629, 175; POxy 246, 16; BGU 759, 11; PAmh 134, 5; TestSol 9:9 C [manuscrito V]; TestAbr B; TestJob 16:6; TestGad 1:6; Fílon; Josefo, Ant. 7, 148; Aristides 10, 7; Justino, D. 134, 5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:12</a> (Timeu, historiador [sécs. IV/III a.C.]: 566 Fgm. 56a Jac., <span class=\"greek\">αὐτοὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">θρέμματα</span> <span class=\"greek\">αὐτῶν</span>, «eles próprios e seus rebanhos»). — DELG, s.v. <span class=\"greek\">τρέφω</span> A; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρηνέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Imperfeito <span class=\"greek\">ἐθρήνουν</span>; futuro <span class=\"greek\">θρηνήσω</span>; 1º aoristo <span class=\"greek\">ἐθρήνησα</span>; futuro passivo, 3ª pessoa do singular <span class=\"greek\">θρηνηθήσεται</span>, Mq 2:4 (ver verbete seguinte; Homero e outros; LXX; TestSol 1:6 D; TestAbr B 6 p. 110, 1 [Stone p. 68]; TestZeb 4:5; ApcEsdr 5:27 p. 31, 1 Tdf.; Aristides; Justino). Em geral, «expressar o pesar», muitas vezes mediante sons e ritmos estabelecidos pelo costume funerário em diferentes regiões do mundo antigo (cf. Il. 24, 722; Od. 24, 61).</p><p class=\"entry-text\">① Expressar-se em tons de tristeza: lamentar, prantear, intransitivo (com <span class=\"greek\">κλαίειν</span>, Justino, D. 141, 3; cf. Jl 1:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16:20</a>.</p><p class=\"entry-text\">② Expressar-se numa canção ou hino de pesar: entoar lamentação fúnebre, intransitivo (Esopo, Fab. 369 H. [mulheres que pranteiam]; LXX), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:32</a>. Como variante <span class=\"greek\">ἐθρήνησε</span> em lugar de <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">θρῆνον</span>, GJs 3:1 (códice A).</p><p class=\"entry-text\">③ Lamentar ritualmente a morte de alguém: prantear, lamentar, com acusativo <span class=\"greek\">τινά</span>, «alguém» (Herodiano 3, 4, 6; Nicetas Eugêniano 7, 182 H.; LXX; Fílon, Leg. All. 3, 231; Josefo, Bell. 3, 436; Aristides 8, 2; Justino, D. 95, 2 <span class=\"greek\">ἑαυτούς</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:27</a> (com <span class=\"greek\">κόπτεσθαι</span>, como Xenófanes: Vorsokr. 21 Testimon. A 13; Mq 1:8; Josefo, Ant. 6, 377; ver E. Martino, Morte e pianto rituale nel mondo antico, ’58, 195–235). <span class=\"greek\">δύο</span> <span class=\"greek\">θρήνους</span> <span class=\"greek\">ἐθρήνει</span>, GJs 2:1. Ver <span class=\"greek\">κόπτω</span> 2.</p><p class=\"entry-text\">— P. Heinisch, Die Totenklage im AT, ’31; C. Westermann, Struktur u. Geschichte der Klage im AT: ZAW 66, ’54, 44–80; P. Ferris, The Genre of Communal Lament in the Bible and the Ancient Near East, ’92 (AT); C. Buresch, Consolationum a Graecis Romanisque scriptarum historia critica, 1886; E. Reiner, Die Rituelle Totenklage der Griechen, ’38; M. Alexiou, The Ritual Lament in Greek Tradition, ’74. Referências adicionais: Betz, SM 120. — DELG, s.v. <span class=\"greek\">θρῆνος</span>; sobre o campo semântico, ver Schmidt, Syn. III 378ss.; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρῆνος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver verbete anterior; Homero e outros.)</p><p class=\"entry-text\">① Expressão ritual de lamento pelos mortos: canto fúnebre, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:18</a>, variante de leitura (Jr 38:15).</p><p class=\"entry-text\">② Expressão de pesar em sentido geral: lamentação. <span class=\"greek\">Ἄννα</span> <span class=\"greek\">δύο</span> <span class=\"greek\">θρήνους</span> <span class=\"greek\">ἐθρήνει</span>, «Ana entoava dois lamentos», GJs 2:1. <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">θρῆνον</span>, GJs 3:1 (ver <span class=\"greek\">θρηνέω</span> 2). — DELG; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρησκεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Também -<span class=\"greek\">ία</span>; Heródoto e posteriores; inscrições, papiros, LXX, Fílon, Josefo, Taciano, Melitão, HE 4, 26, 7; Teófilo de Antioquia 3, 29 [p. 266, 24]; não se restringe às divindades, ver Boffo, Iscrizioni n.º 39, 3; ver verbete seguinte.) Expressão de devoção a seres transcendentes, sobretudo manifesta em ritos cultuais: culto, adoração; o ser adorado é indicado pelo genitivo objetivo (Eliano, NA 10, 28 <span class=\"greek\">τοῦ</span> <span class=\"greek\">Σαράπιδος</span>; Herodiano 4, 8, 7 <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; inscrição délfica em SIG 801d, 4 <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἀπόλλωνος</span>; Sb 14:27 <span class=\"greek\">τ</span>. <span class=\"greek\">εἰδώλων</span>; Fílon, Spec. Leg. 1, 315 <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span>; Josefo, Ant. 1, 222; 12, 271 <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>).</p><p class=\"entry-text\"><span class=\"greek\">θρησκεύειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θρησκείαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὑψίστου</span>, «praticar o culto do Altíssimo», 1Cl 45:7. <span class=\"greek\">θ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγγέλων</span>, «culto dos anjos», Cl 2:18 (M. Dibelius, Hdb., excursus a 2:23 [bibliografia; também A. Williams, JTS 10, 1909, 413–38]. — CB I/2 p. 541 n.º 404 e p. 741 n.º 678 testemunham o culto aos anjos na Frígia. O Concílio de Laodiceia, cânon 35, rejeitou-o; Teodoreto III 490 [sobre Cl 2:16] lamenta sua persistência na Frígia e na Pisídia).</p><p class=\"entry-text\">Acerca da tradição cultual judaica: <span class=\"greek\">ἡμετέρα</span> <span class=\"greek\">θ</span>., «nossa religião», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:5</a> (cf. 4Mc 5:7 e Josefo, Ant. 12, 253 <span class=\"greek\">Ἰουδαίων</span> [genitivo subjetivo] <span class=\"greek\">θ</span>.; Pseudo-Clemente, Hom. 5, 27). Acerca do cristianismo: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀνήκοντα</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἡμῶν</span>, «as coisas próprias de nossa religião», 1Cl 62:1. <span class=\"greek\">τὴν</span> <span class=\"greek\">θ</span>. <span class=\"greek\">προσάγειν</span> <span class=\"greek\">θεῷ</span>, «prestar culto a Deus», Dg 3:2.</p><p class=\"entry-text\">Tiago contrapõe a <span class=\"greek\">μάταιος</span> <span class=\"greek\">θ</span>., «religião vã», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:26</a>, à do v. 27, a <span class=\"greek\">θ</span>. <span class=\"greek\">καθαρὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀμίαντος</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεῷ</span>, «religião pura e imaculada diante de Deus», constituída por boas obras (Herm. Wr. 12, 23 <span class=\"greek\">θρησκεία</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">μία</span> <span class=\"greek\">ἐστί</span>, <span class=\"greek\">μὴ</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">κακόν</span>). — J. van Herten, <span class=\"greek\">Θρησκεία</span>, <span class=\"greek\">εὐλάβεια</span>, <span class=\"greek\">ἱκέτης</span>, diss. Utrecht, ’34; cf. L. Robert, Études épigraphiques et philologiques, ’38, 226–35. Ver <span class=\"greek\">εὐλαβέομαι</span>. — B. 1463; DELG, s.v. <span class=\"greek\">θρησκεύω</span>; M-M; EDNT; TW; Spicq; Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρησκεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver verbete anterior; Heródoto e outros; SIG 783, 42s. [27 a.C.] <span class=\"greek\">τοὺς</span> <span class=\"greek\">θεοὺς</span> <span class=\"greek\">ἐθρήσκευσεν</span> <span class=\"greek\">εὐσεβῶς</span>; Sb 991, 7 [séc. III d.C.]; Herm. Wr. 12, 23 <span class=\"greek\">τοῦτον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span>, <span class=\"greek\">ὦ</span> <span class=\"greek\">τέκνον</span>, <span class=\"greek\">προσκύνει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θρήσκευε</span>; Sb 11:15; 14:17; TestJob 2:2; Justino, A I, 62, 2.) Praticar ritos cultuais, adorar, com acusativo daquilo que é adorado ou servido (Dionísio de Halicarnasso 2, 23, 1 <span class=\"greek\">τοὺς</span> <span class=\"greek\">θεούς</span>; Celso 8, 66; SIG [ver acima]; Herm. Wr. [ver acima]; Sb 11:15; Josefo, Ant. 8, 248; 9, 289; SibOr 5, 77; mas cf. Teófilo de Antioquia 2, 35 [p. 186, 18], com dativo, possivelmente sob influência dos termos relacionados <span class=\"greek\">προσκυνέω</span> e <span class=\"greek\">λατρεύω</span>).</p><p class=\"entry-text\"><span class=\"greek\">πῶς</span> <span class=\"greek\">θρησκεύοντες</span> <span class=\"greek\">αὐτόν</span> (isto é, <span class=\"greek\">τ</span>. <span class=\"greek\">θεόν</span>), «como o adorais», Dg 1. <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span>, «servir ou adorar alguém por meio de alguma coisa», Dg 2:8; <span class=\"greek\">θ</span>. <span class=\"greek\">θρησκείαν</span>, «praticar o culto», 1Cl 45:7. — DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρησκός, όν</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver os dois verbetes anteriores; Hesíquio; Etym. Mag. p. 455, 9; <span class=\"greek\">θρῆσκος</span>, L-S-J-M [léxico]; Sófocles, Lex.) Religioso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:26</a>. — B. 1463; DELG, s.v. <span class=\"greek\">θρησκεύω</span>; TW; Spicq; Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θριαμβεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">1º aoristo <span class=\"greek\">ἐθριάμβευσα</span> (Ctésias; Políbio; Diodoro Sículo 16, 90, 2; Dionísio de Halicarnasso; Epicteto 3, 24, 85 e outros; não é empréstimo do latim — ver B-D-F §5, 1 e L-S-J-M, s.v. <span class=\"greek\">θρίαμβος</span> II). O verbo <span class=\"greek\">θ</span>. aparece somente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 2:14</a> e Cl 2:15. Seguem-se as interpretações principais:</p><p class=\"entry-text\">① Conduzir numa procissão triunfal, na imagem (cf. Sêneca, On Benefits 2, 11, 1) do triunfo militar romano (lat. triumphare; Plutarco, Rom. 33, 4; Arato 1052 [54, 8]; Apiano, Mithrid. 77 §338; 103 §482; Josefo, Bell. 7, 123–57; cf. Teofilacto Simocata, Ep. 68), com acusativo <span class=\"greek\">τινά</span>, «alguém», como cativo.</p><p class=\"entry-text\">ⓐ A respeito de Paulo: <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πάντοτε</span> <span class=\"greek\">θριαμβεύοντι</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Χριστῷ</span>, «graças a Deus, que continuamente nos conduz como cativos na procissão triunfal de Cristo» (REB), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 2:14</a>. O padrão retórico da epístola parece favorecer essa interpretação.</p><p class=\"entry-text\">ⓑ A respeito da vitória de Deus sobre forças hostis: <span class=\"greek\">θριαμβεύσας</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span>, «em conexão com ele (Cristo), Deus os expõe (os poderes transcendentes hostis) em triunfo», Cl 2:15.</p><p class=\"entry-text\">② Conduzir em triunfo, na imagem dos generais romanos que conduzem suas tropas no triunfo (ver Josefo, Bell. 7, 5, 4–6); assim numerosos estudiosos e traduções entendem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 2:14</a>: <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">κτλ</span>., «graças a Deus, que sempre nos conduz como participantes do triunfo em Cristo». Como não existe apoio lexical para essa interpretação (L-S-J-M cita a passagem, mas sem testemunho externo), outros propõem a passagem do significado «conduzir em triunfo» ao sentido seguinte.</p><p class=\"entry-text\">③ Fazer triunfar. Esta interpretação (KJV, Beza, Calvino, Klöpper, Schmiedel, Belser, G. Godet, Sickenberger, ad loc.; semelhantemente Weizsäcker) continua sem exemplos comprovados no uso grego (é muito questionável apelar a Ctésias: 688 Fgm. 13 [Pers. 13] p. 461, 8 Jac. nesse sentido; ver 6, abaixo).</p><p class=\"entry-text\">④ Triunfar sobre é preferido por muitos para Cl 2:15 (Melitão, P. 102, 781, acerca de Cristo: <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">καταλύσας</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θάνατον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θριαμβεύσας</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐχθρόν</span>. — Na passiva: <span class=\"greek\">δι</span>’ … <span class=\"greek\">σταυροῦ</span> … <span class=\"greek\">ἐθριαμβεύθη</span> <span class=\"greek\">σατανᾶς</span>, Serapião de Tmuis, Euch. 25, 2).</p><p class=\"entry-text\">⑤ Expor à vergonha (Marshall; ver também Lietzmann, HNT, ad loc. e apêndice; cf. Ctésias [ver 3 acima; a sequência textual é controvertida] <span class=\"greek\">θριαμβεύσας</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">μάγον</span>, «depois de desmascarar publicamente o mago»). Nesse caso, a imagem do triunfo é absorvida por uma metáfora que expressa o pouco apreço em que Deus permite que o ministério do apóstolo seja tido. Cl 2:15 também pode ser entendido assim. (A ideia de que o próprio termo <span class=\"greek\">θρ</span>. exprima o paradoxo de um apóstolo humilhado e uma missão vitoriosa [Williamson, ver 6 abaixo] é semanticamente insustentável.) <span class=\"greek\">ἀναστενάζων</span>, <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἐθριαμβεύετο</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span>, «gemendo porque se tornara objeto do ridículo da cidade», AcPl Ha 4, 12s.</p><p class=\"entry-text\">⑥ Exibir, tornar público, dar a conhecer (Ctésias: 688 Fgm. 16 [Pers. 58, a respeito da cabeça e da mão direita de um inimigo morto] p. 472, 30 Jac.; ver Lietzmann, Hdb., ad loc.; <span class=\"greek\">ἐκθριαμβίζω</span>, BGU 1061 [14 a.C.]), mudança semântica defendida por Egan para ambas as passagens neotestamentárias (<span class=\"greek\">παύσασθε</span> <span class=\"greek\">λόγους</span> <span class=\"greek\">ἀλλοτρίους</span> <span class=\"greek\">θριαμβεύοντες</span>, «cessai de exprimir [abertamente] essas opiniões estranhas», Taciano 26, 1). — Windisch deixa a escolha em aberto entre 3 e 6.</p><p class=\"entry-text\">— L. Williamson Jr., Int 22, ’68, 317–32; R. Egan, NovT 19, ’77, 34–62; Field, Notes 181s.; R. Pope, ET 21, 1910, 19–21; 112–14; A. Kinsey, ibid., 282s.; F. Prat, RSR 3, 1912, 201–29; H. Versnel, Triumphus, ’70; P. Marshall, NovT 25, ’83, 302–17; C. Breytenbach, Neot. 24, ’90, 250–71; J. Scott, NTS 42, ’96, 260–81; cf. T. Schmidt, NTS 41, ’95, 1–18, sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.16-32\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:16–32</a>. — Contra a imagem do triunfo, J. McDonald, JSNT 17, ’83, 35–50. — DELG, s.v. <span class=\"greek\">θρίαμβος</span>; M-M; EDNT; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρίξ, τριχός, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e posteriores.) Pelo, cabelo.</p><p class=\"entry-text\">ⓐ De animais: <span class=\"greek\">τρίχες</span> <span class=\"greek\">καμήλου</span>, «pelos de camelo»: <span class=\"greek\">ἔνδυμα</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τρ</span>. <span class=\"greek\">κ</span>., «veste de pelos de camelo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:4</a>. Assim, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:6</a> diz de João Batista que estava <span class=\"greek\">ἐνδεδυμένος</span> <span class=\"greek\">τρίχας</span> <span class=\"greek\">κ</span>., «vestido de pelos de camelo». — Acerca de animais apocalípticos de pelos compridos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:8</a> (J. Michl, BZ 23, ’36, 266–88; Biblica 23, ’42, 192s.).</p><p class=\"entry-text\">ⓑ De cabelos humanos (Josefo, Ant. 15, 86; C. Ap. 1, 282): cabelos brancos ou pretos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:36</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:14</a>. <span class=\"greek\">τρίχες</span> <span class=\"greek\">πρεσβύτεραι</span>, «de pessoa mais idosa», isto é, grisalhos, Hv 3, 10, 4s.; 3, 12, 1. <span class=\"greek\">τρ</span>. <span class=\"greek\">λευκαί</span>, 4, 2, 1. <span class=\"greek\">οὐδὲν</span> … <span class=\"greek\">οὔτε</span> <span class=\"greek\">θρὶξ</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">βλέφαρον</span>, «nada, nem um cabelo nem um cílio» (<span class=\"greek\">βλ</span>. aparentemente = <span class=\"greek\">βλεφαρί</span>, por sinédoque), AcPlCor 2:30.</p><p class=\"entry-text\">Quanto a cair facilmente (<span class=\"greek\">ἐκ</span> ou <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κεφαλῆς</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.34\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:34</a> (cf. 1Km 14:45). <span class=\"greek\">αἱ</span> <span class=\"greek\">τρίχες</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κεφαλῆς</span> <span class=\"greek\">πᾶσαι</span>, «todos os cabelos da cabeça», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:7</a> (Alceu 39, 10 [80, 10 D.2]: <span class=\"greek\">παρὰ</span> <span class=\"greek\">μοῖραν</span> <span class=\"greek\">Διὸς</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">τρίχες</span> [o texto se interrompe aqui], «contra a vontade de Zeus, nem sequer os cabelos ...» — Sobre o cabelo como algo sem valor: Paroem. Gr. Zen. [época de Adriano] 2, 4 <span class=\"greek\">ἡ</span> <span class=\"greek\">θρὶξ</span> <span class=\"greek\">οὐδενὸς</span> <span class=\"greek\">ἀξία</span>); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:38</a> (<span class=\"greek\">αἱ</span> <span class=\"greek\">τρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">κεφαλῆς</span>, como Jdt 10:3; Sl 39:13; Fílon, Leg. ad Gai. 223), 44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:2</a>; 12:3.</p><p class=\"entry-text\"><span class=\"greek\">ἐμπλοκὴ</span> <span class=\"greek\">τριχῶν</span>, «trançado dos cabelos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:3</a>. <span class=\"greek\">τρίχας</span> <span class=\"greek\">λελυμένη</span>, «com os cabelos soltos», Hs 9, 9, 5; cf. 9, 13, 8. <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μιᾷ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τρ</span>. <span class=\"greek\">αὐτοῦ</span>, «segurar alguém por um único fio de seu cabelo», GHb 20, 61. <span class=\"greek\">τρίχες</span> <span class=\"greek\">ὀρθαί</span>, «cabelos arrepiados» (Il. 24, 359; Luciano, Philops. 22), Hv 3, 1, 5. — DELG; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θροέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">1º aoristo, particípio passivo <span class=\"greek\">θροηθείς</span> (autores trágicos e outros; na ativa e média, com os sentidos de «gritar, contar, falar, anunciar» etc. — na ativa, Josefo, Ant. 18, 234; 19, 137). No NT somente na passiva, no sentido de «estar interiormente agitado» (cf. Tetrast. Iamb. 2, 1, 4 p. 286; Malalas 41, 12; Ct 5:4), estar perturbado ou assustado (TestAbr B 111, 7 [Stone p. 70]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2:2</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">θροεῖσθε</span>, «não vos assusteis», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:7</a>; AcPl Ha 5, 25. <span class=\"greek\">θροηθέντες</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔμφοβοι</span> <span class=\"greek\">γενόμενοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:37</a>, variante de leitura. — DELG, s.v. <span class=\"greek\">θρέομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρόμβος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Autores trágicos, Heródoto e outros.) Gota: <span class=\"greek\">θ</span>. <span class=\"greek\">αἵματος</span> (Ésquilo, Choëph. 533; 546; Platão, Critias p. 120a; também autores médicos [Hobart 82s.]), «pequena quantidade de sangue corrente», «coágulo de sangue», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:44</a> (Justino, D. 103, 8). — W. Surbled-Sleumer, D. Moral in ihren Beziehungen z. Medizin u. Hygiene II2, 1919, 183ss. — DELG; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρόνος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e posteriores; inscrições, papiros, LXX, pseudoepígrafos; Josefo, Ant. 7, 353; 8, 399; Melitão, P. 83, 620 [B]; empréstimo no hebraico rabínico).</p><p class=\"entry-text\">① Cadeira, assento.</p><p class=\"entry-text\">ⓐ Em geral: <span class=\"greek\">ἐκάθισεν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θρόνου</span>, «(Maria) sentou-se em sua cadeira», GJs 11:1 (JosAs 7:1 <span class=\"greek\">Ἰωσὴφ</span> <span class=\"greek\">ἐκάθισεν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">θρόνου</span>, «José sentou-se numa cadeira»).</p><p class=\"entry-text\">ⓑ Especificamente, cadeira reservada a alguém de posição elevada: trono.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. De reis e governantes humanos (Heródoto 1, 14, 3; Xenofonte, Cyr. 6, 1, 6; Herodiano 1, 8, 4): <span class=\"greek\">καθελεῖν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">θρόνων</span>, «destronar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:52</a>. O trono de Davi (2Km 3:10; PsSol 17:6), antepassado do Messias, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:30</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. De Deus (Sófocles, Ant. 1041; OGI 383 [inscrição de Antíoco de Comagena] 41s. <span class=\"greek\">πρὸς</span> <span class=\"greek\">οὐρανίους</span> <span class=\"greek\">Διὸς</span> <span class=\"greek\">Ὠρομάσδου</span> <span class=\"greek\">θρόνους</span>; Sl 46:9; Ezequiel Trágico, v. 68 [em Eusébio, PE 9, 29, 5]; TestSol 13:5 C): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 7:15</a>; 12:5; 22:1, 3; cf. 1:4; 3:21b; 4:2ss., 9; 5:1, 6s., 11, 13 e outros (ver Cat. Cod. Astr. IX/2 p. 118s., notas e bibliografia). — <span class=\"greek\">ὁ</span> <span class=\"greek\">θρόνος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χάριτος</span>, «trono da graça», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:16</a>; <span class=\"greek\">τ</span>. <span class=\"greek\">μεγαλωσύνης</span>, «da Majestade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:1</a>.</p><p class=\"entry-text\">Do céu como trono de Deus (conforme Is 66:1): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:34</a>; 23:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.49\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:49</a>; B 16:2 (as duas últimas passagens são citações diretas de Is 66:1). — Cf. Theosophien 56, 33s. Sobre o céu como trono de Zeus, ver Orfeu: Hymn. 62, 2s. Q.; Demóstenes 25, 11.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. De Cristo, que ocupa o trono de seu antepassado Davi (ver <span class=\"greek\">α</span> acima). É um <span class=\"greek\">θ</span>. <span class=\"greek\">δόξης</span> <span class=\"greek\">αὐτοῦ</span>, «trono de sua glória», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:28a</a>; 25:31 (PsSol; 2:19); trono eterno, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:8</a> (Sl 44:7), que fica à direita do trono do Pai, Pol 2:1, ou é até mesmo idêntico a ele, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 22:1</a>, 3; cf. 3:21b. Os que lhe pertencem compartilharão com ele esse trono, v. 21a.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. Dos 12 apóstolos como juízes (Filócoro [sécs. IV/III a.C.]: 328 Fgm. 64b<span class=\"greek\">β</span> Jac., os <span class=\"greek\">νομοφύλακες</span> … <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">θρόνων</span> <span class=\"greek\">ἐκάθηντο</span>; Plutarco, Mor. 807b; Pausânias 2, 31, 3; Sl 121:5; Josefo, Ant. 18, 107), ou governantes no tempo da consumação final, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:28b</a> (Galeno X 406 K., <span class=\"greek\">Θέσσαλος</span> <span class=\"greek\">ἅμα</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">σοφισταῖς</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὑψηλοῦ</span> <span class=\"greek\">θρόνου</span> <span class=\"greek\">καθήμενος</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:30</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 20:4</a>.</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. Dos 24 anciãos de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4:4</a>; 11:16. — O Apocalipse também menciona tronos de poderes infernais: o trono do dragão, que a «besta» recebe, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13:2</a>; cf. 16:10. — <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Σατανᾶ</span>, «o trono de Satanás», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:13</a>, na carta a Pérgamo, é frequentemente (p. ex., Deissmann, LO 240, 8 [LAE 280, 2]; Lohmeyer, ad loc.; Boll 112, 4) entendido como o célebre altar de Zeus ali existente (cf. En 25:3, o monte cujo pico se assemelha a um trono); outros (Zahn; J. Weiss, RE X 551) preferem o templo de Asclépio, e Bousset considera Pérgamo o centro do culto imperial. — T. Birt, D. Thron d. Satans: PhilologWoch 52, ’32, 259–66.</p><p class=\"entry-text\">② Poder supremo sobre uma entidade política: domínio, soberania; extensão figurada da acepção 1 (componente semântico provavelmente presente em algumas passagens mencionadas, já que a ideia de autoridade está intimamente ligada à cadeira reservada a quem governa): <span class=\"greek\">θ</span>. <span class=\"greek\">αἰώνιος</span>, «domínio eterno», acerca de Jesus Cristo, 1Cl 65:2; MPol 21.</p><p class=\"entry-text\">③ Nome de uma classe de seres poderosos, terrenos ou transcendentes: «os entronizados», no plural (TestLevi 3:8; cf. a fonte astrológica PMich 149 XVI, 23 e 24 [séc. II d.C.]. — Kephal. I 117, 24–26, personificação daquele que se assenta no trono, o juiz), talvez de seres transcendentes, Cl 1:16 (cf. Melitão, P. 83, 620; D. Sanger em EDNT, s.v.), mas, tendo em vista a menção a coisas «visíveis e invisíveis» no mesmo versículo, é provável que o autor também pense em governantes terrenos (ver 2 acima). — B. 481; DELG; 1628–31; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θρύπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Platão e outros; POxy 471, 80 [séc. II d.C.]; Sl 57:8, Símaco; Fílon; Josefo, Bell. 4, 563.) Quebrar em pedaços pequenos, esmigalhar. <span class=\"greek\">θρυπτόμενον</span>, «que está sendo partido», como acréscimo a <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ὑμῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11:24</a>, no Códice D (cf. Díon Crisóstomo 60 + 61 [77 + 78], 41; Sorano p. 34, 10 <span class=\"greek\">θρυπτόμενον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span>; Nicandro, Ther. 108 <span class=\"greek\">ἂν</span> <span class=\"greek\">σάρκες</span> <span class=\"greek\">θρύπτωνται</span>; Galeno: CMG V/4, 2 p. 148, 23 <span class=\"greek\">θρύμμα</span> <span class=\"greek\">ἄρτου</span>; Diodoro Sículo 1, 83, 3 <span class=\"greek\">καταθρύπτοντες</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἄρτους</span>). — DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θυάτειρα (-ιρα), ων, τά</h1><div class=\"entry-meta\"><span>nome geográfico neutro plural</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Políbio 16, 1, 7; 32, 27, 10; Estrabão 13, 4, 4; Ptolomeu 5, 2, 14; Apiano, Syr. 30 §150; inscrições. Sobre o acusativo em -<span class=\"greek\">αν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:11</a>, variante de leitura, ver B-D-F §57; Mlt-H. 128.) Tiatira, cidade da Lídia, na Ásia Menor, às margens do rio Lico, entre Pérgamo e Sardes, fundada por gregos macedônios (ver Estrabão, loc. cit.; OGI 211 com nota 2).</p><p class=\"entry-text\">Seu movimentado comércio e atividade industrial incluíam, notavelmente, o tingimento de tecidos púrpura. Havia em Tiatira uma associação de tintureiros (<span class=\"greek\">βαφεῖς</span>), cuja existência é atestada por numerosas inscrições (CIG 3497–98 [= IGR IV, 1213; 1265]; 3496; outras inscrições em W. Buckler, Monuments de Thyatire: Rev. de philol. 37, 1913, 289–331. Também a inscrição que a associação de tintureiros de púrpura de Tessalônica dedicou a certo Menipo de Tiatira: L. Duchesne e Ch. Bayet, Mission au Mont Athos, 1876, p. 52 n.º 83). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:11</a>; 2:18, 24.</p><p class=\"entry-text\">— E. Ziebarth, RhM 51, 1896, 632ss.; A. Wikenhauser, Die Ap-Gesch., 1921, 410s. (bibliografia); C. Hemer, The Letters to the Seven Churches of Asia in Their Local Setting, ’86, 106–28 (sobre as fontes epigráficas, ver p. 244s.); Kraft, Hdb., ’74, 67ss.; BHHW III 1981; Pauly-W. VI/1, 657–59. — M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυγάτηρ, τρός, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e posteriores.) Vocativo <span class=\"greek\">θύγατερ</span> (B-D-R 147, 3), em cujo lugar também se usa o nominativo sem artigo (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:15</a>; W-S. §29, 4; Mlt-H. 136); plural <span class=\"greek\">θυγατέρες</span> etc.</p><p class=\"entry-text\">① Ser humano do sexo feminino na relação de descendência com pai ou mãe: filha (<span class=\"greek\">θ</span>. também se usa na literatura a respeito da prole de animais, por exemplo Simônides de Ceos 7, para mulas) (Epicteto 4, 11, 35; Pausânias 8, 20, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:35</a>, 37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:42</a>; 12:53. Seguido de genitivo do pai ou da mãe: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:18</a>; 14:6; 15:22, 28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:35</a>; 6:22; 7:26, 29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:36</a>; 8:49; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:17</a> (Jl 3:1); 7:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:24</a>; B 19:5; D 4:9; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:9</a>; GJs 17:1; Pápias (2:9; 11:2). <span class=\"greek\">τὰς</span> <span class=\"greek\">θυγατέρας</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἑβραίων</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀμιάντους</span>, «as filhas imaculadas dos hebreus», GJs 6:1 (ver de Strycker, ad loc.; também bibliografia s.v. <span class=\"greek\">γαμίζω</span> 1b<span class=\"greek\">γ</span>).</p><p class=\"entry-text\">② Pessoa tratada como filha: filha (sobre esse uso ampliado de <span class=\"greek\">θ</span>., cf. Paradoxogr. Vat. 60 Keller; Fálaris, Ep. 142, 3 <span class=\"greek\">θ</span>. = «menina»); vocativo em saudação afetuosa a meninas ou mulheres, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:48</a>. Semelhantemente, das filhas de Deus como crianças em sentido transcendente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6:18</a> (cf. Is 43:6; Sb 9:7); na saudação pessoal <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θυγατέρες</span>, «filhos e filhas», B 1:1 (cf. Atenágoras 32, 2).</p><p class=\"entry-text\">③ Mulheres pertencentes a um grupo ancestral, entidade política ou classe específica de pessoas: filhas, <span class=\"greek\">θυγατέρες</span> <span class=\"greek\">Ἀαρών</span>, «descendentes femininas de Arão», isto é, mulheres de famílias sacerdotais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:5</a>. <span class=\"greek\">θ</span>. <span class=\"greek\">Ἀβραάμ</span>, «filha de Abraão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:16</a> (cf. 4Mc 15:28). Mulheres que leem B e, portanto, são suas discípulas, B 1:1 (mas ver 2 acima). <span class=\"greek\">θυγατέρες</span> <span class=\"greek\">Ἰερουσαλήμ</span>, «filhas de Jerusalém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:28</a>, expressão veterotestamentária que designa cada uma das habitantes da cidade (cf. Ct 2:7; 3:5; Is 3:16; 4:4; PsSol 2:6, 13). Mas a situação é diferente do uso <span class=\"greek\">θυγάτηρ</span> <span class=\"greek\">Σιών</span>, na acepção 4.</p><p class=\"entry-text\">④ Algo personificado como figura feminina: filha (Procópio Sofista, Ep. 93, as cartas são <span class=\"greek\">θυγατέρες</span> de seus autores); acerca da dúvida: <span class=\"greek\">θ</span>. <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span>, «é filha do diabo», Hm 9:9; cf. 12, 2, 2 (Píndaro, O. 10, 3s., <span class=\"greek\">ἀλάθεια</span> como <span class=\"greek\">θυγάτηρ</span> <span class=\"greek\">Διός</span>). Das virtudes, cada uma das quais é sucessivamente filha de outra, Hv 3, 8, 4s.</p><p class=\"entry-text\">De especial interesse é o singular <span class=\"greek\">θυγάτηρ</span> <span class=\"greek\">Σιών</span>, que, segundo o uso do AT (cf. Zc 2:14; 9:9; Jr 4:31 e outros — SibOr 3, 324 <span class=\"greek\">θυγατέρες</span> <span class=\"greek\">δυσμῶν</span> = «povos do Ocidente»), designa a cidade de Sião e seus habitantes, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:15</a> (ambos combinam Is 62:11 e Zc 9:9). — B. 106; BHHW III 1999; J. Leipoldt, Die Frau in der antiken Welt u. im Urchristentum, ’62; B. Rawson, The Roman Family: The Family in Ancient Rome, org. B. Rawson, ’86, 1–57. — DELG; M-M; EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θυγάτριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro diminutivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver verbete anterior; Estrátis Cômico [c. 400 a.C.], Fgm. 63 Kock; Menandro, Fgm. 361 Kö.; Mácon, v. 348 [em Ateneu 13, 581c]; Plutarco, Mor. 179e; Epicteto 1, 11, 4; Díon Crisóstomo 10 [11], 54; SIG 364, 55; PPetr III, 53 r, 2; PLond I, 24, 6 p. 32 [163 a.C.]; Josefo, Ant. 19, 200. — W. Schmid, D. Attizismus IV, 1897, 305.) Diminutivo de <span class=\"greek\">θυγάτηρ</span>: filhinha (embora a palavra também possa designar alguém em idade de casar-se: Luciano, Tox. 22), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:23</a>, aqui talvez, tendo em vista o diálogo, como expressão de carinho; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7:25</a>. — DELG, s.v. <span class=\"greek\">θυγάτηρ</span>; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύελλα, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e outros; Pseudo-Aristóteles, De Mundo 4 p. 395a, 6: <span class=\"greek\">θύελλα</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">βίαιον</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἄφνω</span> <span class=\"greek\">προσαλλόμενον</span>; Josefo, Bell. 2, 396; 3, 368; SibOr 4, 115.) Perturbação atmosférica caracterizada por rajadas violentas de vento: tempestade, vendaval, redemoinho, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:18</a> (cf. Dt 4:11; 5:22). — DELG, s.v. 1 <span class=\"greek\">θύω</span>; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θύϊνος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Estrabão 4, 6, 2 e outros; talvez também PLond III, 928, 20 p. 191 [séc. II a.C.].) Proveniente da árvore de madeira aromática (tuia), <span class=\"greek\">ξύλον</span>, «madeira de tuia» (Dioscórides 1, 22; 3Km 10:11, Símaco), isto é, madeira perfumada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18:12</a>. — DELG, s.v. 2 <span class=\"greek\">θύω</span> A2; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0170-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θῦμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">θύω</span>; autores trágicos, Tucídides e posteriores; OGI 332, 40 [séc. II a.C.] e outras inscrições; Mitt-Wilck. I/2, 1 III, 3 [séc. III a.C.]; frequente na LXX; Justino, A I, 12, 5; A II, 5, 4.) Sacrifício, oferta, PtK 2 p. 14, 20. — DELG, s.v. 2 <span class=\"greek\">θύω</span> B1.</p></section></article>\n"};
